function U.now()
return os.clock()
end
function U.json(sb)
local tb,ub=pcall(J.JSONEncode,J,sb)
return tb and ub or czd[1682]
end
function U.unjson(vb)
local wb,xb=pcall(J.JSONDecode,J,vb)
return wb and xb or nil
end
function U.readJson(yb)
local zb,Ab=pcall(function()
return isfile(yb)and readfile(yb)or nil
end)
return zb and Ab and U.unjson(Ab)or nil
end
function U.writeJson(Bb,Cb)
pcall(function()
if not isfolder(N.FOLDER)then
makefolder(N.FOLDER)
end
end)
pcall(writefile,Bb,U.json(Cb))
end
function U.fmt(Db)
Db=tonumber(Db)or 0
if Db>=1e6 then
return string.format(czd[1683],Db/1e6)
end
if Db>=1e4 then
return string.format(czd[1684],Db/1e3)
end
return tostring(math.floor(Db+0.5))
end
function U.clamp(Eb,Fb,Gb)
return math.max(Fb,math.min(Gb,Eb))
end
function U.count(Hb)
local Ib=0
for Jb in pairs(Hb or{})do
Ib=Ib+1
end
return Ib
end
function U.list(Kb)
if type(Kb)~=czd[1685]then
return{}
end
if#Kb>0 then
return Kb
end
local Lb={}
for Mb in pairs(Kb)do
table.insert(Lb,Mb)
end
table.sort(Lb,function(Nb,Ob)
return(tonumber(Nb)or 0)<(tonumber(Ob)or 0)
end)
local Pb={}
for Qb,Rb in ipairs(Lb)do
table.insert(Pb,Kb[Rb])
end
return Pb
end
function U.flat(Sb)
return Vector3 .new(Sb.X,0,Sb.Z)
end
function U.plain(Tb,Ub)
local Vb=type(Tb)
if Vb==czd[1686]or Vb==czd[596]or Vb==czd[1687]then
return Tb
end
if Vb~=czd[1685]or(Ub or 0)>6 then
return nil
end
local Wb={}
for Xb,Yb in pairs(Tb)do
if type(Xb)==czd[1686]or type(Xb)==czd[596]then
Wb[Xb]=U.plain(Yb,(Ub or 0)+1)
end
end
return Wb
end
function F.log(Zb,_b,cc)
if Zb>(O.logLevel or 1)then
return
end
local dc=string.format(czd[1688],os.date(czd[1689]),_b,tostring(cc))
table.insert(R.lines,dc)
if#R.lines>250 then
table.remove(R.lines,1)
end
table.insert(R.pending,dc)
local ec=tostring(cc):lower()
if ec:find(czd[1690])or ec:find(czd[1691])or ec:find(czd[1692])or _b==czd[1693]then
R.problems=R.problems or{}
table.insert(R.problems,dc)
if#R.problems>30 then
table.remove(R.problems,1)
end
end
if O.logConsole then
print(czd[1694]..dc)
end
end
function F.status(fc,gc)
Q[fc]=gc
F.statusAt=F.statusAt or{}
F.statusAt[fc]=os.time()
end
function F.flush()
if#R.pending==0 then
return
end
local hc=table.concat(R.pending,czd[1695])..czd[1695]
table.clear(R.pending)
pcall(function()
if not isfolder(N.FOLDER)then
makefolder(N.FOLDER)
end
if appendfile and isfile(N.LOGFILE)then
appendfile(N.LOGFILE,hc)
else
writefile(N.LOGFILE,hc)
end
end)
end
task.spawn(function()
while F.alive do
task.wait(3)
F.flush()
end
end)
do
local jc=U.readJson(N.SETTINGS)or{}
if jc.shareChosen~=true then
jc.shareStats=nil
end
if jc.autoTeamChosen~=true then
jc.autoTeam=nil
end
for kc,lc in pairs(N.DEFAULTS)do
if jc[kc]~=nil and type(jc[kc])==type(lc)then
O[kc]=jc[kc]
else
O[kc]=lc
end
end
O.seenVersion=type(jc.seenVersion)==czd[596]and jc.seenVersion or nil
if jc.griffinWatch==true and jc.snipeUnit==nil then
O.snipeOn,O.snipeUnit=true,czd[767]
end
if O.pickPortal==czd[613]then
O.portals,O.pickPortal=false,czd[612]
end
if O.huntCards==czd[1696]then
O.huntCards=czd[1697]
end
O.cfgv=1
if not O.simpleGui then
O.simpleGui=true
if not O.play then
O.master=false
end
O.play=true
for mc,nc in ipairs({czd[1698],czd[1699],czd[1700],czd[1701],czd[1702],czd[1703],czd[1704],czd[1705]})do
O[nc]=true
end
end
end
