for xk,yk in pairs(type(pk._strong_against)==czd[1685]and pk._strong_against or type(pk.strong_against)==czd[1685]and pk.strong_against or{})do
local zk=type(yk)==czd[1685]and yk.damage_type or(type(yk)==czd[596]and yk)or nil
