end
W._levelMod[Fk]=false
local Gk=N.Levels[Fk]
local Hk=type(Gk)==czd[1685]and N.Waves[Gk.waves or Fk]
local Ik=type(Hk)==czd[1685]and Hk.initial_unit_configs
if type(Ik)~=czd[1685]then
return nil
end
local Jk,Kk,Lk={},{},0
for Mk,Nk in pairs(Ik)do
local Ok=type(Nk)==czd[1685]and type(Nk.override_stats)==czd[1685]and(Nk.override_stats[1]or Nk.override_stats[czd[1851]])or nil
if type(Ok)==czd[1685]then
local Pk=tonumber(Ok.health)or 20
Lk=Lk+Pk
table.insert(Jk,{hp=Pk,st=Ok})
for Qk in pairs(Ok)do
local Rk=tostring(Qk):match(czd[1822])or tostring(Qk):match(czd[1852])
if Rk then
Kk[Rk]=true
end
end
end
end
if not next(Kk)or Lk<=0 then
return nil
end
local Sk={weak={},strong={},res={}}
for Tk in pairs(Kk)do
local Uk=0
for Vk,Wk in ipairs(Jk)do
local Xk=(1+(tonumber(Wk.st[czd[1853]..Tk])or 0))*100/(100+math.max(0,tonumber(Wk.st[czd[1854]..Tk])or 0))
Uk=Uk+Wk.hp/math.max(0.05,Xk)
end
local Yk=Lk/math.max(1,Uk)
if Yk>1.02 then
Sk.weak[Tk]=Yk
elseif Yk<0.98 then
Sk.res[Tk]=Yk
end
end
if not(next(Sk.weak)or next(Sk.res))then
return nil
end
W._levelMod[Fk]=Sk
return Sk
end
