xo=xo+1
end
end
uo=uo+xo*kb.lineGems()/so.core.SIZE
table.insert(vo,czd[1904])
end
if ro and ro~=czd[1905]and not so.weathers[ro]then
uo=uo+(1000+5000*O.pearlValue+50*W.remnantGems(czd[1903]))/kb.WEATHERS
table.insert(vo,czd[1906])
