F.saveSoon()
F.log(1,czd[1944],string.format(czd[1945],kb.charmWords(cq),tostring(bq.label),math.floor((tonumber(bq.p)or 0)*100+0.5),(tonumber(bq.p)or 0)>=0.92 and czd[1936]or czd[1847]))
else
