end
end
function kb.weatherStrength(fq)
local gq=kb.fx(fq)
local hq=gq.dmg/gq.cd/gq.hp/gq.speed*(1+(gq.range-1)/2)
for iq,jq in pairs(gq.kinds)do
hq=hq*(1+bb.rogueShare(iq)*jq)
end
if gq.ice>0 then
local kq=bb.rogueShare(czd[1819])
hq=hq*(kq+(1-kq)/(1-gq.ice+gq.ice/fb.modFactor(czd[1947])))
end
if gq.fly>0 then
hq=hq*(1-gq.fly*0.5)
end
if gq.noCC then
hq=hq*0.95
end
if gq.shroud then
hq=hq*0.9
end
if gq.zap then
hq=hq*0.85
end
return hq/kb.weatherK(fq)
end
kb.WEATHER_K_MIN,kb.WEATHER_K_MAX,kb.WEATHER_K_RUNS=0.5,4,10
function kb.weatherK(lq)
local mq=lq and type(P.hunt)==czd[1685]and type(P.hunt.wk)==czd[1685]and P.hunt.wk[tostring(lq)]or nil
return type(mq)==czd[1685]and tonumber(mq.k)or 1
end
function kb.weatherLearn()
if bb.withOthers or#game:GetService(czd[589]):GetPlayers()>1 then
return
end
local nq=bb.huntWeather or kb.weatherNow()
local oq,pq=bb.pred,bb.calRun
if not nq or type(oq)~=czd[1685]or type(pq)~=czd[1685]then
return
end
local function qq(rq,sq)
return type(rq)==czd[1685]and tonumber(rq[sq]or rq[tostring(sq)])or nil
end
local tq={}
for uq=2,bb.wave()do
local vq,wq=qq(pq.alive,uq),qq(oq.aliveAt,uq)
if vq and wq and vq>0 and wq>0 then
table.insert(tq,vq/wq)
end
end
if#tq<3 then
return
end
table.sort(tq)
local xq=tq[math.ceil(#tq/2)]
P.hunt.wk=type(P.hunt.wk)==czd[1685]and P.hunt.wk or{}
local yq=P.hunt.wk[tostring(nq)]
local zq=math.min(kb.WEATHER_K_RUNS-1,type(yq)==czd[1685]and tonumber(yq.n)or 0)
local Aq=kb.weatherK(nq)
local Bq=math.max(1,zq)
local Cq=math.exp((Bq*math.log(Aq)+math.log(Aq*xq))/(Bq+1))
Cq=U.clamp(Cq,kb.WEATHER_K_MIN,kb.WEATHER_K_MAX)
bb.wkWas={w=tostring(nq),old=yq}
P.hunt.wk[tostring(nq)]={k=Cq,n=(type(yq)==czd[1685]and tonumber(yq.n)or 0)+1,at=os.time()}
F.log(1,czd[1948],string.format(czd[1949],tostring(nq),xq,tostring(nq),Cq,Aq,P.hunt.wk[tostring(nq)].n))
end
function kb.cardGems(Dq,Eq)
