return jb.RELIC_SETTLED_GAIN
end
return jb.RELIC_MOVE_GAIN
end
function jb.relicWorth(TQ,UQ)
local VQ=UQ._unique_item_data and UQ._unique_item_data._unique_relic_data
if not VQ then
return 0
end
local WQ=N.Items[UQ.item_id]or{}
local XQ,YQ=V.types(TQ.unit_id)
if WQ.main_damage_type and WQ.main_damage_type~=czd[2399]and WQ.main_damage_type~=YQ then
return 0
end
local ZQ,_Q=0,0
for aR,bR in pairs(VQ._core_damage_type_buffs or{})do
if XQ[bR.damage_type]then
ZQ=ZQ+(tonumber(bR.mul)or 0)+(tonumber(bR.add_upg)or 0)*0.01+(tonumber(bR.pen)or 0)*0.001
_Q=_Q+(tonumber(bR.crit)or 0)
end
end
ZQ=ZQ+_Q*0.5
local cR=V.rows(TQ.unit_id)
local dR=cR and cR[cR.max]
local eR=(dR and tonumber(dR.cd)or 0)*V.mult(TQ,czd[1848])
for fR,gR in pairs(VQ._unique_relic_effects or{})do
local hR=type(gR.params)==czd[1685]and gR.params or{}
if gR.id==czd[2400]then
local iR=math.min(1,(tonumber(hR.extra_damage)or 0)*eR/math.max(1,tonumber(hR.time_interval)or 40))
local jR=V.DRONES and V.DRONES[TQ.unit_id]
if jR and jR.late and eR>0 then
local kR=1/eR
iR=iR*kR/(kR+(tonumber(jR.max)or 0)*(tonumber(jR.late.dmg)or 0)*(tonumber(jR.hits)or 1)/math.max(0.1,tonumber(jR.late.cd)or 4))
end
ZQ=ZQ+iR
elseif gR.id==czd[2401]then
ZQ=ZQ+(tonumber(hR.dmg_buff)or 0)*0.25
elseif gR.id==czd[2402]then
ZQ=ZQ+(tonumber(hR.dmg_buff)or 0)*_Q
elseif gR.id==czd[2403]then
if XQ.magic then
ZQ=0
else
ZQ=ZQ+(tonumber(hR.dmg_buff)or 0)*0.3
end
elseif gR.id==czd[2404]then
if XQ.water_damage then
ZQ=ZQ+0.05
end
end
end
return ZQ
end
function jb.relicPlan()
local lR=N.session()
if not lR then
return nil
end
local mR=lR.inventory and lR.inventory.inventory_profile_data or{}
local nR={}
for oR,pR in ipairs(mR.unique_items or{})do
if type(pR)==czd[1685]and pR.uuid and(N.Items[pR.item_id]or{}).item_group==czd[2405]then
table.insert(nR,pR)
end
end
local qR={}
for rR,sR in ipairs(V.equipped())do
local tR=sR.data and sR.data.rarity
if not V.isFarm(sR.id)and(tR==czd[1977]or tR==czd[1978]or tR==czd[2384]or tR==czd[2406])then
local uR=jb.share(sR.id)
if not P.str.share[sR.id]then
uR=math.min(uR,0.15)
end
local vR={}
for wR,xR in ipairs(nR)do
local yR=jb.relicWorth(sR.u,xR)*uR*100
if yR>0.01 then
table.insert(vR,{it=xR,w=yR})
end
end
table.sort(vR,function(zR,AR)
if zR.w~=AR.w then
return zR.w>AR.w
end
return zR.it.uuid<AR.it.uuid
end)
local BR,CR={},{}
for DR,ER in ipairs(vR)do
local FR=CR[ER.it.item_id]or 0
if#BR<6 and FR<((N.Items[ER.it.item_id]or{}).unique_equip and 1 or 2)then
CR[ER.it.item_id]=FR+1
table.insert(BR,ER)
end
end
if sR.u._equipped_relic then
local GR=false
for HR,IR in ipairs(BR)do
if IR.it.uuid==sR.u._equipped_relic then
GR=true
end
end
local JR=not GR and lR.inventory:get_item_by_uuid(sR.u._equipped_relic)
if JR then
table.insert(BR,{it=JR,w=jb.relicWorth(sR.u,JR)*uR*100})
end
end
table.insert(qR,{e=sR,share=uR,opts=BR})
end
end
local KR,LR={},-1
local MR,NR,OR={},{},{}
local function PR(QR,RR)
if QR> #qR then
if RR>LR then
LR=RR
KR=table.clone(MR)
end
return
end
local SR=qR[QR]
MR[SR.e.uuid]=nil
PR(QR+1,RR)
for TR,UR in ipairs(SR.opts)do
local VR=(N.Items[UR.it.item_id]or{}).unique_equip
if not NR[UR.it.uuid]and not(VR and OR[UR.it.item_id])then
NR[UR.it.uuid]=true
if VR then
OR[UR.it.item_id]=true
end
MR[SR.e.uuid]=UR.it.uuid
PR(QR+1,RR+UR.w+(UR.it.uuid==SR.e.u._equipped_relic and 0.01 or 0))
MR[SR.e.uuid]=nil
NR[UR.it.uuid]=nil
if VR then
OR[UR.it.item_id]=nil
end
end
end
end
PR(1,0)
local WR,XR=0,{}
for YR,ZR in ipairs(qR)do
local _R=ZR.e.u._equipped_relic and lR.inventory:get_item_by_uuid(ZR.e.u._equipped_relic)
local aS=_R and jb.relicWorth(ZR.e.u,_R)*ZR.share*100 or 0
WR=WR+aS
local bS=KR[ZR.e.uuid]and lR.inventory:get_item_by_uuid(KR[ZR.e.uuid])
local cS=bS and jb.relicWorth(ZR.e.u,bS)*ZR.share*100 or 0
table.insert(XR,string.format(czd[2407],V.name(ZR.e.id),_R and(N.Items[_R.item_id]or{}).name or czd[1988],aS,bS and(N.Items[bS.item_id]or{}).name or czd[1988],cS))
end
return KR,LR-WR,XR,qR
end
function jb.relicsApply(dS)
if not(O.team and O.teamRelics)or O.strDry then
return false
end
local eS=W.teamSig()
if not dS and P.str.relicSig==eS and os.time()-(tonumber(P.str.relicAt)or 0)<600 then
return false
end
if F.req.back.relicMove and U.now()<F.req.back.relicMove then
return false
end
P.str.relicSig,P.str.relicAt=eS,os.time()
local fS,gS,hS,iS=jb.relicPlan()
if not fS then
return false
end
P.str.relicNote=string.format(czd[2408],math.max(0,gS))
if gS<jb.relicBar()then
P.str.relicTeam=eS
return false
end
local jS=N.session()
local kS=jS.profile_data.collection.owned_units
local function lS(mS)
for nS,oS in pairs(kS)do
if oS._equipped_relic==mS then
return nS,oS
end
end
end
local function pS(qS)
return F.gameSaid(qS)or czd[2001]
end
local function rS(sS)
local tS,uS=lS(sS)
if not tS then
return true
end
local vS=U.now()
F.request(czd[2409],czd[2410],sS)
while U.now()-vS<4 and uS._equipped_relic==sS do
task.wait(0.25)
end
task.wait(1.2)
if uS._equipped_relic==sS then
F.log(1,czd[2390],string.format(czd[2411],V.name(uS.unit_id),tostring(V.relicName(uS)),pS(vS)))
F.backoff(czd[2409],300)
return false
end
return true
end
F.log(1,czd[2390],string.format(czd[2412],gS,table.concat(hS,czd[1914])))
for wS,xS in ipairs(iS)do
local yS=xS.e.u._equipped_relic
if yS and yS~=fS[xS.e.uuid]and not rS(yS)then
return false
end
end
for zS,AS in pairs(fS)do
local BS=lS(AS)
if BS and BS~=zS and not rS(AS)then
return false
end
end
table.sort(iS,function(CS,DS)
return CS.share>DS.share
end)
local ES=0
for FS,HS in ipairs(iS)do
local IS=fS[HS.e.uuid]
if IS and HS.e.u._equipped_relic~=IS then
local JS,KS=0,nil
local LS={}
for MS,NS in ipairs(V.equipped())do
LS[NS.uuid]=true
end
for OS,PS in pairs(kS)do
if PS._equipped_relic then
JS=JS+1
if not LS[OS]and(not KS or not table.find(P.str.core or{},OS))then
KS=PS._equipped_relic
end
end
end
if JS>=jb.MAX_RELICS and KS and not rS(KS)then
return false
end
local QS=U.now()
F.request(czd[2409],czd[1943],IS,{unit_uuid=HS.e.uuid})
while U.now()-QS<4 and HS.e.u._equipped_relic~=IS do
task.wait(0.25)
end
task.wait(1.2)
if HS.e.u._equipped_relic~=IS then
F.log(1,czd[2390],string.format(czd[2413],(N.Items[(jS.inventory:get_item_by_uuid(IS)or{}).item_id]or{}).name or czd[2414],V.name(HS.e.id),pS(QS)))
F.backoff(czd[2409],300)
P.str.relicAt=0
return false
end
ES=ES+1
end
end
W._sigAt=nil
P.str.relicSig=W.teamSig()
P.str.relicTeam=P.str.relicSig
P.str.relicNote=string.format(czd[2415],gS)
jb.note(string.format(czd[2416],ES,gS))
return true
end
function jb.foodHeld()
local RS=N.session()
local TS={}
local US=RS and RS.inventory and RS.inventory.inventory_profile_data or{}
for VS,WS in pairs(US.normal_items or{})do
local XS=N.Items[VS]
if type(XS)==czd[1685]and type(XS.usage)==czd[1685]and XS.usage.type==czd[2417]and(tonumber(WS)or 0)>0 then
table.insert(TS,{id=VS,n=tonumber(WS),xp=tonumber(XS.usage.xp_amount)or 0})
end
end
table.sort(TS,function(YS,ZS)
return YS.xp>ZS.xp
end)
return TS
end
function jb.xpRoom()
local _S,aT=N.session(),0
for bT,cT in ipairs(_S and jb.core()or{})do
local dT=_S.collection:get_unit_by_uuid(cT)
if dT then
aT=aT+math.max(0,jb.xpFor(dT.unit_id,jb.cap(dT))-(tonumber(dT.xp)or 0))
end
end
return aT
end
function jb.plan()
local eT=N.session()
if not eT then
return{}
end
local fT={}
local gT=jb.core()
local hT=jb.foodHeld()
local iT=0
for jT,kT in ipairs(hT)do
iT=iT+kT.n*kT.xp
end
local lT=O.autoFuse and O.fuseUnit~=czd[610]and O.fuseUnit or nil
local mT=(P.fuseInfo and tonumber(P.fuseInfo.requirement))or(P.lb and tonumber(P.lb.requirement))or 12
local nT=gb.have(czd[2383])
for oT,pT in ipairs(gT)do
local qT=eT.collection:get_unit_by_uuid(pT)
if qT then
local rT,sT=qT.unit_id,V.name(qT.unit_id)
local tT=jb.role(rT)
if O.teamXp and iT>0 then
local uT,vT=jb.gainXp(qT,iT)
local wT,xT=jb.gainXp(qT,500000)
local yT=xT>0 and wT/xT*vT or 0
if vT>0 and yT>0 then
local zT=jb.feedPlan(qT)
local AT,BT=jb.level(qT),jb.level({unit_id=rT,xp=(tonumber(qT.xp)or 0)+vT})
table.insert(fT,{kind=czd[2418],uuid=pT,name=sT,gain=yT,add=vT,planned=zT.planned,items=zT.n,lvl0=AT,lvl1=jb.level({unit_id=rT,xp=(tonumber(qT.xp)or 0)+(zT.planned>0 and zT.planned or vT)}),text=string.format(czd[2419],sT,U.fmt(vT),BT>AT and string.format(czd[2420],AT,BT)or string.format(czd[2421],AT),yT)})
end
end
local CT=P.str.fuseNo and tonumber(P.str.fuseNo[pT])
if O.teamFuse and jb.lb(qT)==0 and tT~=czd[1703]and pT~=lT and not(CT and os.time()-CT<86400)then
local ET=jb.gainFuse(qT)
local FT=jb.xpFor(rT,jb.cap(qT))<=(tonumber(qT.xp)or 0)
local GT,HT,IT=pcall(ab.fuseFuel,qT,mT)
IT=GT and IT or 0
local JT=(not FT and czd[2422])or(nT<1 and czd[2423])or(IT<mT and string.format(czd[2424],math.floor(IT),math.floor(mT)))or nil
local KT=(not FT and czd[2425])or(nT<1 and czd[2426])or(IT<mT and czd[2427])or nil
table.insert(fT,{kind=czd[2428],uuid=pT,name=sT,gain=ET,blocked=JT,blockKind=KT,got=IT,need=mT,wish=nT,lvl=jb.level(qT),cap=jb.cap(qT),text=string.format(czd[2429],sT,ET)})
end
end
end
table.sort(fT,function(LT,NT)
if LT.gain~=NT.gain then
return LT.gain>NT.gain
end
return LT.text<NT.text
end)
for OT in pairs(V._mult)do
if type(OT)==czd[596]and OT:sub(1,5)==czd[2393]then
V._mult[OT]=nil
end
end
P.str.acts,P.str.actsAt={},os.time()
for PT=1,math.min(12,#fT)do
local QT=fT[PT]
table.insert(P.str.acts,{kind=QT.kind,uuid=QT.uuid,name=QT.name,gain=QT.gain,text=QT.text,blocked=QT.blocked,blockKind=QT.blockKind,got=QT.got,need=QT.need,wish=QT.wish,lvl=QT.lvl,cap=QT.cap,add=QT.add,planned=QT.planned,items=QT.items,lvl0=QT.lvl0,lvl1=QT.lvl1})
end
return fT
end
function jb.itemWorth(RT)
if not(P.str.acts and os.time()-(tonumber(P.str.actsAt)or 0)<900)then
return nil
end
local TT={}
for UT,VT in ipairs(P.str.acts)do
if VT.gain and(not TT[VT.kind]or VT.gain>TT[VT.kind])then
TT[VT.kind]=VT.gain
end
end
local WT=O.strengthValue or 300
if RT==czd[2383]then
return TT.fuse and math.max(N.ITEM_VALUE.divine_wish or 400,TT.fuse*WT)or nil
end
return nil
end
function jb.xpRate()
local XT=N.session()
if not XT then
return 0
end
local YT=0
for ZT,_T in ipairs(jb.core())do
local aU=XT.collection:get_unit_by_uuid(_T)
if aU then
local bU,cU=jb.gainXp(aU,500000)
if cU>0 then
YT=math.max(YT,bU/cU)
end
end
end
local dU=YT*(O.strengthValue or 300)
if(tonumber(N.cur(czd[1749]))or 0)>(O.xpGoldFloor or 100000)then
dU=math.min(dU,(N.GOLD_VALUE or 0.02)/14)
end
return dU
end
function jb.xpGuess(eU)
local fU=eU.level and N.Levels[eU.level]
if not fU then
return 0
end
local gU=math.min(9,tonumber(fU.story_world_rank)or tonumber(eU.rank)or 9)
local hU=tonumber(fU.story_level_rank)or 6
local iU=(eU.kind==czd[1723]and 1.5 or 1)*(gU>5 and 2 or 1)
local jU=2.1564^(gU-1)*(40+10*hU)/iU
if eU.kind==czd[1704]then
jU=3*30*2.1564^(gU-1)/iU
end
local kU=gU>=9 and 0.3 or(gU>=7 and 0.5 or 1)
return jU*kU*6
end
function jb.modeBonus(lU)
if not(O.team and O.teamXp)or lU.kind==czd[1705]or lU.kind==czd[1702]then
return 0
end
local mU=jb._xpRate and os.time()-(jb._xpRateAt or 0)<300 and jb._xpRate or nil
if not mU then
mU=jb.xpRate()
jb._xpRate,jb._xpRateAt=mU,os.time()
end
if mU<=0 then
return 0
end
local nU=P.modes and P.modes[lU.key]
local oU=tonumber(nU and nU.xp)or jb.xpGuess(lU)
local pU=oU*mU
if pU<1 then
return 0
end
return pU,string.format(czd[2430],U.fmt(oU),math.floor(pU+0.5))
end
function jb.xpSettle()
local qU=P.lastRun
if not(qU and type(qU.xp0)==czd[1685]and qU.key)then
return
end
local rU=N.session()
if not rU then
return
end
local sU,tU=0,0
for uU,vU in pairs(qU.xp0)do
local wU=rU.collection:get_unit_by_uuid(uU)
if wU then
sU=sU+math.max(0,(tonumber(wU.xp)or 0)-(tonumber(vU)or 0))
tU=tU+1
end
end
P.lastRun=nil
if tU==0 then
return
end
local xU=W.rec(qU.key)
xU.xp=xU.xp and(xU.xp+(sU-xU.xp)*0.3)or sU
if sU>0 then
F.log(2,jb.LOG,string.format(czd[2431],qU.key,U.fmt(sU)))
end
F.saveSoon()
end
function jb.note(yU)
F.log(1,jb.LOG,yU)
table.insert(P.str.log,1,{at=os.time(),msg=yU})
while#P.str.log>20 do
table.remove(P.str.log)
end
F.saveSoon()
end
function jb.feedPlan(zU)
local AU=V.trait(zU)
local BU=AU==czd[2432]and 1.5 or 1
local CU=math.max(0,jb.xpFor(zU.unit_id,jb.cap(zU))-(tonumber(zU.xp)or 0))
local DU,EU,FU={},0,0
for GU,HU in ipairs(jb.foodHeld())do
local IU=HU.xp*BU
local JU=math.min(HU.n,math.floor((CU-EU)/math.max(1,IU)))
if JU>0 then
DU[HU.id]=JU
EU=EU+JU*IU
FU=FU+JU
end
end
return{feed=DU,planned=EU,n=FU}
end
function jb.run(KU)
local MU=N.session()
local NU=MU and MU.collection:get_unit_by_uuid(KU.uuid)
if not NU then
return
end
if KU.kind==czd[2418]then
local OU=jb.feedPlan(NU)
local PU,QU,RU=OU.feed,OU.planned,OU.n
if RU==0 then
P.str.feedNote=KU.name..czd[2433]
return
end
local SU,TU=tonumber(NU.xp)or 0,jb.level(NU)
local UU,VU=F.request(czd[2418],czd[2434],KU.uuid,PU)
local WU=U.now()
while U.now()-WU<4 and(tonumber((MU.collection:get_unit_by_uuid(KU.uuid)or NU).xp)or 0)<=SU do
task.wait(0.25)
end
local XU=MU.collection:get_unit_by_uuid(KU.uuid)or NU
local YU=(tonumber(XU.xp)or 0)-SU
if YU>0 then
local ZU=jb.level(XU)
local _U=ZU>TU and string.format(czd[2420],TU,ZU)or string.format(czd[2421],TU)
cb.add(string.format(czd[2435],RU,KU.name),RU,czd[2436],string.format(czd[2437],U.fmt(YU),_U))
jb.note(string.format(czd[2438],KU.name,RU,U.fmt(YU),_U,math.abs(YU-QU)>QU*0.1 and string.format(czd[2439],U.fmt(QU))or czd[610]))
else
jb.note(string.format(czd[2440],KU.name,tostring(UU and VU or czd[2001])))
F.backoff(czd[2418],600)
end
elseif KU.kind==czd[2428]then
ab.fuseInto(KU.uuid,false)
end
end
function jb.slotOf(aV)
local bV=N.session()
for cV,dV in pairs(bV and bV.profile_data.collection.equipped_units or{})do
if dV==aV then
return tonumber(cV)or cV
end
end
