function jb.reequip()
local eV=P.str.reequip
if not eV then
return true
end
local fV=N.session()
local gV=fV and fV.collection:get_unit_by_uuid(eV.uuid)
if not gV then
P.str.reequip=nil
return true
end
for hV=1,3 do
if jb.slotOf(eV.uuid)then
break
end
F.request(czd[2441],czd[2442],eV.uuid)
local iV=U.now()
while U.now()-iV<3 and not jb.slotOf(eV.uuid)do
task.wait(0.25)
end
end
W._sigAt=nil
if jb.slotOf(eV.uuid)then
P.str.reequip=nil
F.saveSoon()
return true
end
F.log(1,czd[2443],string.format(czd[2444],V.name(gV.unit_id),tostring(eV.slot)))
return false
end
jb.REMOTE={feed=czd[2418],fuse=czd[2428]}
jb.WORK_MAX=300
