if not mV.blocked and not(nV and U.now()<nV)and(tonumber(P.str.noWork[mV.kind])or 0)<=kV and(tonumber(P.str.noWork[mV.kind..czd[1810]..tostring(mV.uuid)])or 0)<=kV then
