jb.FEED_STOP_GAIN=0.5
function jb.focusReady()
if not(O.autoEvolve and O.evolveUnit~=czd[610])then
return nil
end
pcall(gb.refresh)
for rV,sV in ipairs(P.goals or{})do
if sV.pinned and sV.uuid==O.evolveUnit and sV.ready and(ab.evoBlocked[sV.uuid]or 0)<os.time()then
