F.log(1,czd[2032],string.format(czd[2884],edb.label,edb.kind==czd[1865]and czd[2839]or(czd[2885]..((N.Items[(P.watch or{}).portal or czd[610]]or{}).name or czd[1868])),edb.why or czd[610],edb.score or 0))
F.saveNow()
F.status(czd[2461],czd[2886]..edb.label)
local fdb=U.now()
local gdb
if edb.kind==czd[1865]then
_,gdb=F.request(czd[1868],czd[2887],edb.level,{difficulty=czd[1910]})
else
_,gdb=F.request(czd[1868],czd[2888],edb.portal)
end
local hdb=N.svc(czd[2889])
local function idb()
local jdb=hdb and hdb.current_lobby
if jdb then
return jdb
end
local kdb=workspace:FindFirstChild(czd[2890])and workspace._PORTALS:FindFirstChild(czd[2891])
for ldb,mdb in ipairs(kdb and kdb:GetChildren()or{})do
local ndb=mdb:FindFirstChild(czd[2833])
if ndb and ndb.Value==M then
return mdb.Name
end
end
end
local odb
while F.alive and U.now()-fdb<28 and not odb do
odb=idb()
if not odb then
if F.gameSaid(fdb)then
break
end
task.wait(0.5)
end
end
if odb and U.now()-fdb>10 then
F.log(1,czd[2032],string.format(czd[2892],U.now()-fdb))
end
if not odb then
local pdb=F.gameSaid(fdb)
local qdb=pdb and pdb:lower():find(czd[2893],1,true)
ab.badPortal=ab.badPortal or{}
if edb.portal and not qdb then
ab.badPortal[edb.portal]=os.time()+3600
end
local rdb=edb.kind==czd[1865]and not qdb
if rdb then
W.rec(edb.key).restUntil,W.rec(edb.key).restWhy=os.time()+1800,czd[1690]
W.lastScored=nil
end
F.log(1,czd[2032],string.format(czd[2894],edb.kind==czd[1865]and czd[310]or czd[1868],tostring(pdb or gdb or czd[2001]),qdb and czd[2895]or(rdb and czd[2896]or czd[2897])))
task.wait(2)
local sdb=idb()
if sdb then
F.request(czd[2853],czd[2854],sdb)
end
P.pending,P.watch=nil,nil
F.backoff(czd[2828],math.max(5,32-(U.now()-fdb)))
return false
end
task.wait(0.5)
pcall(function()
local tdb=hdb and hdb.more_lobby_params and hdb.more_lobby_params[odb]
local udb=tdb and tdb._level_data
if type(udb)~=czd[1685]then
return
end
local vdb=N.Levels[edb.level]or{}
local wdb={}
for xdb,ydb in pairs(udb)do
local zdb=vdb[xdb]
if type(ydb)~=czd[1685]and type(ydb)~=czd[2611]and ydb~=zdb then
table.insert(wdb,tostring(xdb)..czd[2074]..tostring(ydb))
elseif type(ydb)==czd[1685]and type(zdb)~=czd[1685]then
local Adb,Bdb=pcall(J.JSONEncode,J,ydb)
table.insert(wdb,tostring(xdb)..czd[2074]..(Adb and Bdb:sub(1,120)or czd[2073]))
end
end
table.sort(wdb)
local Cdb= #wdb>0 and table.concat(wdb,czd[1914])or czd[2898]
P.portalMods=Cdb
F.saveNow()
F.log(1,czd[2899],string.format(czd[2900],edb.label,Cdb:sub(1,400)))
local Ddb=Cdb:find(czd[2901])or Cdb:find(czd[1699])or Cdb:find(czd[2902])or Cdb:find(czd[2903])or Cdb:find(czd[2904])
if Ddb and O.autoTeam then
edb.ldOverride=udb
local Edb,Fdb=pcall(ab.teamFor,edb,ab.QUICK_SEARCH)
if not Edb then
F.log(1,czd[2027],czd[2905]..tostring(Fdb))
end
edb.ldOverride=nil
end
end)
local Gdb=U.now()
local Hdb={}
for Idb=1,3 do
local Jdb,Kdb=F.request(czd[2855],czd[2856],odb)
table.insert(Hdb,tostring(Jdb and Kdb))
local Ldb=U.now()
while F.alive and U.now()-Ldb<12 do
task.wait(1)
end
if not F.alive then
return false
end
odb=(hdb and hdb.current_lobby)or odb
end
if F.alive then
local Mdb=F.gameSaid(Gdb)
F.log(1,czd[2032],string.format(czd[2906],table.concat(Hdb,czd[1795]),Mdb and(czd[2907]..Mdb)or czd[610],edb.label,edb.kind==czd[1865]and czd[2908]or czd[2909]))
F.request(czd[2853],czd[2854],odb)
ab.badPortal=ab.badPortal or{}
if edb.portal then
ab.badPortal[edb.portal]=os.time()+3600
end
if edb.kind==czd[1865]then
W.rec(edb.key).restUntil,W.rec(edb.key).restWhy=os.time()+900,czd[2827]
W.lastScored=nil
end
P.pending,P.watch=nil,nil
