function ab.watchDone()
local Rdb=P.watch
if not Rdb then
return
end
P.watch=nil
if os.time()-(tonumber(Rdb.at)or 0)>3*3600 then
return
end
local Sdb=gb.have(Rdb.item)-(tonumber(Rdb.have)or 0)
local Tdb= #W.portalsHeld(Rdb.portal)
local function Udb(Vdb,Wdb)
local Xdb=P.portalPay[Vdb]or{n=0}
Xdb.n=(tonumber(Xdb.n)or 0)+1
Xdb.per=Xdb.per and(Xdb.per+(Wdb-Xdb.per)*math.max(0.25,1/Xdb.n))or Wdb
P.portalPay[Vdb]=Xdb
end
local Ydb,Zdb=(N.Items[Rdb.item]or{}).name or Rdb.item,(N.Items[Rdb.portal]or{}).name or Rdb.portal
if Rdb.used then
ab.portalLine(string.format(czd[2911],os.date(czd[2912]),Sdb,Ydb,gb.have(Rdb.item),Tdb))
if Rdb.won==false then
F.log(1,czd[2899],string.format(czd[2913],W.levelName(W.PORTALS[Rdb.portal].level),Sdb,Ydb,gb.have(Rdb.item),Tdb))
else
Udb(Rdb.portal,math.max(0,Sdb))
F.log(1,czd[2899],string.format(czd[2914],W.levelName(W.PORTALS[Rdb.portal].level),Sdb,Ydb,gb.have(Rdb.item),Tdb))
end
else
local _db=Tdb-(tonumber(Rdb.held)or 0)
Udb(czd[2343]..Rdb.portal,math.max(0,_db))
F.log(1,czd[2899],string.format(czd[2915],W.levelName(W.PORTALS[Rdb.portal].from),_db,Zdb,Tdb,Sdb>0 and string.format(czd[2916],Sdb,Ydb)or czd[610]))
end
W.lastScored=nil
F.saveSoon()
end
function ab.simFresh(aeb)
