return beb and beb.sig==W.teamSig()and os.time()-(beb.at or 0)<6*3600 or false
end
function ab.relicClash(ceb)
local deb=N.session()
local eeb={}
for feb,geb in ipairs(P.savedTeam or{})do
eeb[geb]=true
end
local heb={}
for ieb,jeb in ipairs(ceb)do
local keb=deb.collection:get_unit_by_uuid(jeb)
local leb=keb and keb._equipped_relic and deb.inventory:get_item_by_uuid(keb._equipped_relic)
if leb and leb.item_id and(N.Items[leb.item_id]or{}).unique_equip then
table.insert(heb,{uuid=jeb,u=keb,kind=leb.item_id,relic=keb._equipped_relic,k=(eeb[jeb]and 1e12 or 0)+jb.score(keb)})
end
end
table.sort(heb,function(meb,neb)
if meb.k~=neb.k then
return meb.k>neb.k
end
return meb.uuid<neb.uuid
end)
local oeb={}
for peb,qeb in ipairs(heb)do
if oeb[qeb.kind]then
local reb=(N.Items[qeb.kind]or{}).name or qeb.kind
local seb,teb=F.request(czd[2917],czd[2410],qeb.relic)
local ueb=U.now()
while U.now()-ueb<3 and qeb.u._equipped_relic==qeb.relic do
task.wait(0.25)
end
if qeb.u._equipped_relic~=qeb.relic then
P.relicOff[qeb.uuid]=qeb.relic
F.log(1,czd[2443],string.format(czd[2918],V.name(qeb.u.unit_id),reb,V.name(oeb[qeb.kind])))
else
F.log(1,czd[2443],string.format(czd[2919],V.name(qeb.u.unit_id),reb,tostring(teb)))
end
else
oeb[qeb.kind]=qeb.u.unit_id
end
end
end
function ab.relicBack()
if O.team and O.teamRelics then
table.clear(P.relicOff)
return
end
local veb=N.session()
for web,xeb in pairs(P.relicOff)do
local yeb=veb.collection:get_unit_by_uuid(web)
local zeb=veb.inventory:get_item_by_uuid(xeb)
local Aeb=zeb and zeb._unique_item_data and zeb._unique_item_data._unique_relic_data
if yeb and Aeb and not yeb._equipped_relic and not Aeb._equipped_unit_uuid and not jb.slotOf(web)then
local Beb
for Ceb,Deb in ipairs(V.equipped())do
local Eeb=Deb.u._equipped_relic and veb.inventory:get_item_by_uuid(Deb.u._equipped_relic)
if Eeb and Eeb.item_id==zeb.item_id then
Beb=Deb
end
end
if Beb then
P.str.reequip={uuid=Beb.uuid,slot=Beb.slot}
F.saveNow()
F.request(czd[2003],czd[2004],Beb.uuid)
local Feb=U.now()
while U.now()-Feb<4 and jb.slotOf(Beb.uuid)do
task.wait(0.25)
end
end
F.request(czd[2917],czd[1943],xeb,{unit_uuid=web})
local Geb=U.now()
while U.now()-Geb<3 and yeb._equipped_relic~=xeb do
task.wait(0.25)
end
if Beb then
jb.reequip()
end
F.log(1,czd[2443],string.format(czd[2920],V.name(yeb.unit_id),(N.Items[zeb.item_id]or{}).name or tostring(zeb.item_id),yeb._equipped_relic==xeb and czd[610]or czd[2921]))
end
P.relicOff[web]=nil
end
end
function ab.equipTeam(Heb,Ieb)
local Jeb={}
for Keb,Leb in ipairs(V.equipped())do
Jeb[Leb.uuid]=true
end
if not P.savedTeam then
local Meb={}
for Neb,Oeb in ipairs(V.equipped())do
table.insert(Meb,Oeb.uuid)
end
P.savedTeam=Meb
end
local Peb,Qeb=pcall(ab.relicClash,Heb)
if not Peb then
F.log(1,czd[2027],czd[2922]..tostring(Qeb))
end
local Reb={}
for Seb,Teb in ipairs(Heb)do
Reb[Teb]=true
end
local Ueb,Veb=false,{}
for Web=1,4 do
for Xeb in pairs(Jeb)do
if not Reb[Xeb]then
local Yeb,Zeb=F.request(czd[2003],czd[2004],Xeb)
table.insert(Veb,string.format(czd[2923],V.name((N.session().collection:get_unit_by_uuid(Xeb)or{}).unit_id or czd[1957]),tostring(Zeb)))
task.wait(0.8)
end
end
for _eb,afb in ipairs(Heb)do
if not Jeb[afb]then
local bfb
if Web>2 then
local cfb={}
for dfb,efb in ipairs(V.equipped())do
cfb[efb.slot]=true
end
for ffb=1,6 do
if not cfb[ffb]then
bfb=ffb
break
end
end
end
local gfb,hfb
if bfb then
gfb,hfb=F.request(czd[2441],czd[2442],afb,bfb)
else
gfb,hfb=F.request(czd[2441],czd[2442],afb)
end
table.insert(Veb,string.format(czd[2924],V.name((N.session().collection:get_unit_by_uuid(afb)or{}).unit_id or czd[1957]),bfb and(czd[2925]..bfb)or czd[610],tostring(gfb),tostring(hfb)))
task.wait(0.8)
end
end
local ifb=U.now()
while U.now()-ifb<3 and not hb.same(hb.team(),Heb)do
task.wait(0.25)
end
Ueb=hb.same(hb.team(),Heb)
if Ueb then
break
end
Jeb={}
for jfb,kfb in ipairs(V.equipped())do
Jeb[kfb.uuid]=true
end
end
W._sigAt=nil
if Ueb then
F.log(1,czd[2443],czd[2926].. #Heb..czd[2927]..tostring(Ieb))
else
local lfb={}
for mfb,nfb in ipairs(V.equipped())do
table.insert(lfb,V.name(nfb.id))
end
F.log(1,czd[2443],czd[2928]..tostring(Ieb)..czd[2929]..table.concat(lfb,czd[1795])..czd[2930]..table.concat(Veb,czd[1914]))
if not ab.refilling and#V.equipped()<6 then
ab.refilling=true
local ofb,pfb={},{}
for qfb,rfb in ipairs(V.equipped())do
pfb[rfb.uuid]=true
end
for sfb,tfb in ipairs(P.savedTeam or{})do
if not pfb[tfb]and N.session().collection:get_unit_by_uuid(tfb)then
table.insert(ofb,tfb)
end
end
local ufb=0
for vfb,wfb in ipairs(ofb)do
if#V.equipped()>=6 then
break
end
F.request(czd[2441],czd[2442],wfb)
task.wait(0.8)
local xfb=U.now()
while U.now()-xfb<3 and#V.equipped()<math.min(6,ufb+1+(6- #ofb))do
task.wait(0.25)
end
for yfb,zfb in ipairs(V.equipped())do
if zfb.uuid==wfb then
ufb=ufb+1
end
end
end
local Afb={}
for Bfb,Cfb in ipairs(V.equipped())do
table.insert(Afb,V.name(Cfb.id))
end
F.log(1,czd[2443],string.format(czd[2931],ufb,table.concat(Afb,czd[1795])))
W._sigAt=nil
ab.refilling=nil
end
end
F.saveSoon()
return Ueb
end
function ab.ownSwap()
local Dfb=P.ownSwap
if not Dfb then
return
end
local Efb=F.request(czd[2752],czd[2753])
if not Efb then
return
end
if P.train.on then
hb.home()
end
local Ffb=N.session()
local Gfb=table.clone(P.savedTeam or hb.team())
local Hfb,Ifb
for Jfb,Kfb in ipairs(Gfb)do
local Lfb=Ffb.collection:get_unit_by_uuid(Kfb)
if Lfb and Lfb.unit_id==Dfb.out then
Hfb=Jfb
end
if Lfb and Lfb.unit_id==Dfb.into then
Ifb=true
end
end
local Mfb,Nfb
for Ofb,Pfb in pairs(Ffb.profile_data.collection.owned_units)do
if Pfb.unit_id==Dfb.into and(not Mfb or(tonumber(Pfb.xp)or 0)>Nfb)then
Mfb,Nfb=Ofb,tonumber(Pfb.xp)or 0
end
end
if Ifb or not Hfb or not Mfb then
P.ownSwap=nil
F.log(1,czd[2443],string.format(czd[2932],V.name(Dfb.into),V.name(Dfb.out),Ifb and czd[2933]or not Hfb and czd[2934]or czd[2935]))
return F.saveSoon()
end
Gfb[Hfb]=Mfb
local Qfb=P.savedTeam
P.savedTeam=nil
if ab.equipTeam(Gfb,string.format(czd[2936],V.name(Dfb.into),V.name(Dfb.out)))then
P.savedTeam,P.ownSwap=nil,nil
W.lastScored=nil
if F.notify then
F.notify(czd[2937],string.format(czd[2938],V.name(Dfb.into),V.name(Dfb.out)),czd[2326])
end
else
P.savedTeam=Qfb or P.savedTeam
end
F.saveSoon()
end
function ab.restoreTeam()
if not P.savedTeam then
return false
end
local Rfb={}
for Sfb,Tfb in ipairs(P.savedTeam)do
if N.session()and N.session().collection:get_unit_by_uuid(Tfb)then
table.insert(Rfb,Tfb)
end
end
P.savedTeam=nil
