end
end
F.saveSoon()
return true
end
ab.LAB={EVERY=3,KINDS={story=true,raid=true,infinite=true},MIN_EVIDENCE=5,AGAIN=24*3600}
function ab.unitEvidence(Wfb)
local Xfb=P.learn[Wfb]
local Yfb=Xfb and tonumber(Xfb.n)or 0
local Zfb=db.hive()
local _fb=Zfb and type(Zfb.units)==czd[1685]and Zfb.units[Wfb]
if type(_fb)==czd[1685]then
Yfb=Yfb+(tonumber(_fb.matches)or 0)+(tonumber(_fb.matches3)or 0)
end
return Yfb
end
function ab.unitLabSafe(agb)
if O.unitLab==false or type(agb)~=czd[1685]or not ab.LAB.KINDS[agb.kind]or agb.first then
return false
end
if P.trial or P.study or(type(P.testTeam)==czd[1685]and(tonumber(P.testTeam.left)or 0)>0)or(P.train and P.train.on)or ab.partyRole()~=czd[613]then
return false
end
local bgb,cgb=pcall(ab.matchOn,agb)
if bgb and cgb then
return false
end
local dgb=type(P.unitLab)==czd[1685]and P.unitLab or{}
if dgb.pauseKey==agb.key and os.time()<(tonumber(dgb.pauseUntil)or 0)then
return false
end
local egb=W.rec(agb.key)
local fgb,ggb=tonumber(egb.runs)or 0,tonumber(egb.wins)or 0
if agb.kind==czd[1704]then
local hgb,igb=pcall(W.infDaily,N.prof(),agb.level,W.infReach(agb.key))
return fgb>=3 and hgb and(tonumber(igb)or 1)<=0
end
return fgb>=5 and(tonumber(egb.streak)or 0)==0 and ggb/fgb>=0.9
end
function ab.unitLab(jgb)
if not ab.unitLabSafe(jgb)then
return
end
P.unitLab=type(P.unitLab)==czd[1685]and P.unitLab or{}
local kgb=P.unitLab
kgb.tried=type(kgb.tried)==czd[1685]and kgb.tried or{}
kgb.seen=(tonumber(kgb.seen)or 0)+1
if kgb.seen%ab.LAB.EVERY~=0 then
return
end
local lgb=N.session()
local mgb=V.equipped()
if not lgb or#mgb<2 then
return
end
local ngb={}
for ogb,pgb in ipairs(mgb)do
ngb[pgb.uuid]=true
ngb[pgb.id]=true
end
local qgb,rgb,sgb
for tgb,ugb in pairs(lgb.profile_data.collection.owned_units)do
local vgb=ugb.unit_id
if not ngb[tgb]and not ngb[vgb]and N.Units[vgb]and not V.isFarm(vgb)and not V.allyBuff(vgb)and os.time()-(tonumber(kgb.tried[vgb])or 0)>ab.LAB.AGAIN then
local wgb=ab.unitEvidence(vgb)
if wgb<ab.LAB.MIN_EVIDENCE then
local xgb=lgb.collection:get_unit_by_uuid(tgb)or ugb
local ygb=jb.score(xgb)
if ygb>0 and(not qgb or wgb<rgb or(wgb==rgb and ygb>sgb))then
qgb,rgb,sgb={uuid=tgb,id=vgb,u=xgb},wgb,ygb
end
end
end
end
if not qgb then
return
end
local zgb,Agb
for Bgb,Cgb in ipairs(mgb)do
if not V.isFarm(Cgb.id)and not V.allyBuff(Cgb.id)and Cgb.uuid~=O.evolveUnit then
local Dgb=jb.score(Cgb.u)
if not zgb or Dgb<Agb then
zgb,Agb=Cgb,Dgb
end
end
end
if not zgb then
return
end
kgb.tried[qgb.id]=os.time()
local Egb=0
for Fgb in pairs(kgb.tried)do
Egb=Egb+1
if Egb>300 then
kgb.tried[Fgb]=nil
end
end
local Ggb,Hgb=fb.levelFor(jgb)
if not Ggb then
return
end
local Igb=fb.info(Ggb,jgb.key,Hgb,jgb.mod or W.ldMod(Ggb)or W.levelMod(jgb.level))
local Jgb={}
for Kgb,Lgb in ipairs(mgb)do
table.insert(Jgb,Lgb.uuid==zgb.uuid and qgb.u or Lgb.u)
end
local Mgb,Ngb=pcall(fb.run,Igb,fb.teamFrom(Jgb,Igb.map),{hpMul=1.1})
local Ogb=Mgb and type(Ngb)==czd[1685]and(Ngb.won or(Igb.infinite and(tonumber(Ngb.wave)or 0)>=0.8*W.infReach(jgb.key)))
if not Ogb then
F.log(2,czd[2941],string.format(czd[2942],V.name(qgb.id),jgb.label))
return
end
local Pgb={}
for Qgb,Rgb in ipairs(mgb)do
table.insert(Pgb,Rgb.uuid==zgb.uuid and qgb.uuid or Rgb.uuid)
end
if ab.equipTeam(Pgb,czd[2943]..V.name(qgb.id))then
kgb.now={id=qgb.id,out=zgb.id,key=jgb.key,at=os.time(),ev=rgb}
F.log(1,czd[2941],string.format(czd[2944],V.name(qgb.id),V.name(zgb.id),jgb.label,rgb))
F.saveNow()
end
end
function ab.unitLabDone(Sgb)
local Tgb=P.unitLab
local Ugb=type(Tgb)==czd[1685]and Tgb.now
if type(Ugb)~=czd[1685]then
return
end
Tgb.now,Tgb.restore=nil,true
if bb.key~=Ugb.key then
return
end
local Vgb=bb.lastEff and bb.lastEff[Ugb.id]
Tgb.runs=(tonumber(Tgb.runs)or 0)+1
Tgb.done=type(Tgb.done)==czd[1685]and Tgb.done or{}
Tgb.done[Ugb.id]={at=os.time(),eff=Vgb,won=Sgb and true or false}
Tgb.last=Ugb.id
local Wgb=0
for Xgb in pairs(Tgb.done)do
Wgb=Wgb+1
if Wgb>150 then
Tgb.done[Xgb]=nil
end
