local VJb=vJb[UJb].u.unit_id
if V.allyBuff(VJb)or V.BLESS.by[VJb]or V.GALE[VJb]then
table.insert(FJb,vJb[UJb].u)
end
end
if gJb and((gJb.flyChance or 0)>0 or gJb.mapFly or(gJb.shield or 0)>0)then
local WJb,XJb={},{}
for YJb=11,#vJb do
local ZJb=vJb[YJb].u
local _Jb=V.rows(ZJb.unit_id)[0]
if V.airFrom(ZJb.unit_id)==0 then
table.insert(WJb,ZJb)
end
local aKb,bKb=tonumber(_Jb and _Jb.cd)or 0,tonumber((N.Units[ZJb.unit_id]or{}).cost)or 0
if aKb>0 and bKb>0 and V.range(ZJb,0)>=15 then
local cKb=V.attackInfo(_Jb.atk,_Jb.range)
table.insert(XJb,{u=ZJb,v=cKb.n*cKb.hits/aKb/bKb*math.min(6,V.cap(ZJb))})
end
end
table.sort(XJb,function(dKb,eKb)
return dKb.v>eKb.v
end)
for fKb=1,math.min(4,#WJb)do
table.insert(FJb,WJb[fKb])
end
for gKb=1,math.min(6,#XJb)do
table.insert(FJb,XJb[gKb].u)
end
end
local hKb,iKb={},{}
for jKb,kKb in ipairs(FJb)do
if not hKb[kKb]then
hKb[kKb]=true
table.insert(iKb,kKb)
end
end
iKb.rest={}
for lKb,mKb in ipairs(vJb)do
if not hKb[mKb.u]then
table.insert(iKb.rest,mKb.u)
end
end
return iKb
end
function fb.objective(nKb)
return(nKb.won and 1000 or 0)+nKb.wave*10-(nKb.won and nKb.t/60 or((nKb.left or 1)*9-math.min(9,nKb.t/60)))
end
fb.LADDER={1,1.3,1.7,2.2,3,4,6,8,12,16,24}
function fb.cliff(oKb,pKb,qKb)
local rKb
for sKb,tKb in ipairs(fb.LADDER)do
rKb=fb.run(oKb,pKb,{hpMul=tKb,layout=qKb})
if not rKb.won then
return tKb,rKb
end
end
return fb.LADDER[#fb.LADDER],rKb
end
function fb.exam(uKb,vKb)
local wKb,xKb,yKb=fb.teamFrom(vKb,uKb.map),0,0
for zKb,AKb in ipairs(fb.LADDER)do
