for DKb,EKb in ipairs({0.92,1,1.08})do
local FKb=fb.run(uKb,wKb,{hpMul=AKb*EKb})
if FKb.won then
BKb=BKb+1
end
CKb=CKb+FKb.wave
end
xKb,yKb=xKb+BKb,CKb/3
task.wait()
if BKb==0 then
break
end
end
return xKb,yKb
end
fb.ZONE_CLOSE,fb.ZONE_GAIN=1.3,20
function fb.zoneKey(GKb)
