end
function fb.zoneChoice(HKb,IKb,JKb,KKb)
if O.killZone==false or HKb.zone or(HKb.infinite and fb.unbound(HKb.ld))then
return false
end
local LKb=P.zoneRec[fb.zoneKey(HKb)]
local MKb=LKb and(LKb.style==czd[3121]or(LKb.style==nil and LKb.zone==true))
if LKb and LKb.won then
return MKb==true,MKb and czd[3150]or nil
end
if LKb and MKb then
