end
local NKb=P.modes[HKb.key]
local OKb=NKb and tonumber(NKb.streak)or 0
if not LKb and NKb and(tonumber(NKb.wins)or 0)>0 and OKb==0 and HKb.key~=czd[2091]and HKb.key~=czd[2087]then
return false
end
local PKb=LKb~=nil or OKb>0
local QKb=KKb and JKb<=1 or(not KKb and JKb<=fb.ZONE_CLOSE)
if not(PKb or QKb)then
return false
end
local RKb=table.clone(HKb)
RKb.zone=true
local function SKb(TKb)
