function fb.bestTeam(lLb,mLb,nLb,oLb)
local pLb=U.now()
oLb=oLb or 25
local qLb=table.clone(mLb)
local rLb,sLb=fb.cliff(lLb,fb.teamFrom(qLb,lLb.map))
local function tLb(uLb)
local vLb=0
for wLb,xLb in ipairs(uLb)do
if V.isFarm(xLb.unit_id)then
vLb=vLb+1
end
end
return vLb
end
local yLb=tLb(nLb)>0
local function zLb(ALb)
local BLb=0
for CLb,DLb in ipairs(ALb)do
if not V.isFarm(DLb.unit_id)and not V.allyBuff(DLb.unit_id)then
BLb=BLb+V.cap(DLb)
end
end
return BLb
end
local ELb
while#qLb<6 do
local FLb,GLb
local HLb=yLb and tLb(qLb)==0
for ILb,JLb in ipairs(nLb)do
local KLb=false
for LLb,MLb in ipairs(qLb)do
if MLb.unit_id==JLb.unit_id then
KLb=true
end
end
if not KLb and(not HLb or V.isFarm(JLb.unit_id))then
local NLb=table.clone(qLb)
table.insert(NLb,JLb)
local OLb=fb.run(lLb,fb.teamFrom(NLb,lLb.map),{hpMul=rLb})
local PLb=fb.objective(OLb)
if not GLb or PLb>GLb then
FLb,GLb,ELb=JLb,PLb,OLb
end
end
end
if not FLb then
break
end
table.insert(qLb,FLb)
end
if yLb and tLb(qLb)==0 then
local QLb,RLb
for SLb=1,#qLb do
for TLb,ULb in ipairs(nLb)do
if V.isFarm(ULb.unit_id)then
local VLb=table.clone(qLb)
VLb[SLb]=ULb
local WLb=fb.run(lLb,fb.teamFrom(VLb,lLb.map),{hpMul=rLb})
local XLb=fb.objective(WLb)
if not RLb or XLb>RLb then
QLb,RLb,ELb=VLb,XLb,WLb
end
end
end
end
if QLb then
qLb=QLb
end
end
local function YLb(ZLb,_Lb)
local aMb=fb.teamFrom(ZLb,lLb.map)
return(fb.objective(_Lb)+fb.objective(fb.run(lLb,aMb,{hpMul=rLb*0.92}))+fb.objective(fb.run(lLb,aMb,{hpMul=rLb*1.08})))/3
end
local bMb,cMb=ELb or sLb,YLb(qLb,ELb or sLb)
if type(nLb.rest)==czd[1685]and#nLb.rest>0 then
local dMb,eMb
for fMb,gMb in ipairs(qLb)do
if not V.isFarm(gMb.unit_id)and not V.allyBuff(gMb.unit_id)then
local hMb,iMb=pcall(V.score,gMb,lLb.mod)
iMb=(hMb and iMb or 0)*V.skinMul(gMb,lLb.skinSet)
if not eMb or iMb<eMb then
dMb,eMb=fMb,iMb
end
end
end
if dMb then
local jMb,kMb={},U.now()
for lMb,mMb in ipairs(nLb.rest)do
if U.now()-kMb>5 then
break
end
local nMb=false
for oMb,pMb in ipairs(qLb)do
if pMb.unit_id==mMb.unit_id then
nMb=true
end
end
if not nMb then
local qMb=table.clone(qLb)
qMb[dMb]=mMb
table.insert(jMb,{u=mMb,o=fb.objective(fb.run(lLb,fb.teamFrom(qMb,lLb.map),{hpMul=rLb}))})
end
end
table.sort(jMb,function(rMb,sMb)
return rMb.o>sMb.o
end)
nLb=table.clone(nLb)
for tMb=1,math.min(4,#jMb)do
table.insert(nLb,1,jMb[tMb].u)
end
pLb=pLb+(U.now()-kMb)
end
end
for uMb=1,2 do
local vMb=false
for wMb=1,#qLb do
for xMb,yMb in ipairs(nLb)do
if U.now()-pLb>oLb then
return qLb,bMb,rLb,sLb
end
local zMb=false
for AMb,BMb in ipairs(qLb)do
if BMb.unit_id==yMb.unit_id then
zMb=true
end
end
if not zMb then
local CMb=table.clone(qLb)
CMb[wMb]=yMb
if(not yLb or tLb(CMb)>0)and zLb(CMb)>=math.min(8,zLb(qLb))then
local DMb=fb.run(lLb,fb.teamFrom(CMb,lLb.map),{hpMul=rLb})
local EMb=fb.objective(DMb)
if EMb>cMb+1 then
EMb=YLb(CMb,DMb)
if EMb>cMb+1 then
qLb,cMb,bMb,vMb=CMb,EMb,DMb,true
end
end
end
end
end
end
if not vMb then
break
end
end
return qLb,bMb,rLb,sLb
end
