local cWb={gems=tonumber(N.cur(czd[1747]))or 0,gold=tonumber(N.cur(czd[1749]))or 0,items={},units={},unique=0}
for dWb,eWb in pairs(bWb.normal_items or{})do
cWb.items[dWb]=tonumber(eWb)or 0
end
for fWb,gWb in pairs(aWb.collection and aWb.collection.owned_units or{})do
cWb.units[fWb]=gWb.unit_id
end
for hWb in pairs(bWb.unique_items or{})do
cWb.unique=cWb.unique+1
end
