function ib.walletDiff(iWb,jWb)
local kWb={}
if jWb.gems~=iWb.gems then
table.insert(kWb,string.format(czd[3339],jWb.gems-iWb.gems))
end
if jWb.gold~=iWb.gold then
table.insert(kWb,string.format(czd[3340],jWb.gold-iWb.gold))
end
for lWb,mWb in pairs(jWb.items)do
if mWb~=(iWb.items[lWb]or 0)then
table.insert(kWb,string.format(czd[3341],mWb-(iWb.items[lWb]or 0),tostring(lWb)))
end
end
for nWb,oWb in pairs(jWb.units)do
if not iWb.units[nWb]then
table.insert(kWb,czd[3342]..V.name(oWb))
end
end
if jWb.unique~=iWb.unique then
table.insert(kWb,string.format(czd[3343],jWb.unique-iWb.unique))
end
return#kWb>0 and table.concat(kWb,czd[1795])or czd[3344]
end
function ib.openChests(pWb,qWb)
