local uWb=ib.lives(pWb)
local vWb=ib.cleared(pWb)
if not(qWb or vWb>=ib.ROOMS or uWb<=1)then
ib.note(string.format(czd[3345],vWb,sWb,tWb,ib.luck(pWb)))
F.request(czd[3331],czd[3332])
return
end
local wWb,xWb,yWb=0,0,0
local zWb=tonumber(N.cur(czd[1747]))or 0
local AWb=ib.wallet()
for BWb=1,sWb+tWb+4 do
local CWb,DWb,EWb=ib.res(ib.data())
if DWb+EWb<=0 or yWb>=2 then
break
end
local FWb,GWb
if DWb>0 then
FWb,GWb=F.request(czd[3346],czd[3347])
else
FWb,GWb=F.request(czd[3346],czd[3347],true)
end
if FWb and GWb~=nil then
F.log(1,czd[3315],czd[3348]..(type(GWb)==czd[1685]and U.json(U.plain(GWb)):sub(1,300)or tostring(GWb)))
end
local HWb=U.now()
while U.now()-HWb<4 do
local IWb,JWb,KWb=ib.res(ib.data())
if JWb<DWb or KWb<EWb then
break
end
task.wait(0.25)
end
local LWb,MWb,NWb=ib.res(ib.data())
if MWb<DWb then
wWb=wWb+(DWb-MWb)
yWb=0
elseif NWb<EWb then
xWb=xWb+(EWb-NWb)
yWb=0
else
yWb=yWb+1
end
task.wait(1)
if MWb<DWb or NWb<EWb then
local OWb=ib.wallet()
local PWb=ib.walletDiff(AWb,OWb)
F.log(1,czd[3315],(NWb<EWb and czd[3349]or czd[3348])..PWb)
P.dg.pay=P.dg.pay or{}
local QWb={}
for RWb,SWb in pairs(OWb.items)do
if SWb~=(AWb.items[RWb]or 0)then
QWb[RWb]=SWb-(AWb.items[RWb]or 0)
end
end
table.insert(P.dg.pay,{at=os.time(),rare=NWb<EWb,gems=OWb.gems-AWb.gems,luck=ib.luck(pWb),paid=PWb,items=QWb})
while#P.dg.pay>60 do
table.remove(P.dg.pay,1)
end
AWb=OWb
end
end
ib.note(string.format(czd[3350],wWb,xWb,qWb and czd[3351]or(uWb<=1 and czd[3352]or czd[3353]),ib.luck(pWb),(tonumber(N.cur(czd[1747]))or 0)-zWb))
local TWb,UWb,VWb=ib.res(ib.data())
if(qWb or vWb>=ib.ROOMS)and UWb+VWb>0 then
ib.note(string.format(czd[3354],UWb,VWb))
W.rec(czd[2121]).restUntil=os.time()+1800
return czd[3355]
end
if not qWb then
F.request(czd[3331],czd[3332])
end
end
function ib.act(WWb)
local XWb,YWb=ib.state(WWb)
ib.logState(WWb,XWb)
if XWb==czd[3314]then
return false
end
if XWb==czd[3313]then
ib.note(string.format(czd[3356],tostring(YWb and YWb.t)))
F.request(czd[3331],czd[3332])
return true
end
if XWb==czd[2167]then
F.request(czd[3357],czd[3358])
ib.note(czd[3359])
P.dg.lives,P.dg.lost,P.dg.bailed,P.dg.bails=5,{},{},{}
