end
F.request(czd[3331],czd[3332])
local ZWb,_Wb,aXb=ib.res(ib.data())
table.insert(P.dg.runs,1,{at=os.time(),depth=ib.ROOMS,items=U.count(ib.items(WWb)),left=_Wb+aXb})
while#P.dg.runs>10 do
table.remove(P.dg.runs)
end
ib.note(czd[3360])
elseif XWb==czd[2460]then
ib.shop(WWb,YWb)
elseif XWb==czd[3265]then
ib.shrine(WWb,YWb)
elseif XWb==czd[3312]then
if ib.openChests(WWb,false)==czd[3355]then
return czd[3355]
end
end
return true
end
function ib.launch(bXb)
local cXb=ib.data()
if not cXb then
F.backoff(czd[2828],30)
return false
end
if not cXb._started then
if not(O.dungeonStart or O.onlyDungeons)then
return false
end
local dXb,eXb=F.request(czd[3361],czd[3362])
task.wait(2.5)
cXb=ib.data()
if not(dXb and cXb and cXb._started)then
F.log(1,czd[3315],czd[3363]..tostring(eXb)..czd[3364])
W.rec(czd[2121]).restUntil=os.time()+1800
F.backoff(czd[2828],10)
