function bb.lookAt(Zhc)
local _hc,aic=math.huge,nil
for bic,cic in ipairs(bb.samples)do
local dic=(U.flat(cic.pos)-U.flat(Zhc)).Magnitude
if dic<_hc then
_hc,aic=dic,cic.pos
end
end
local eic=aic and U.flat(aic-Zhc)or Vector3 .new(0,0,-1)
return eic.Magnitude>0.01 and eic.Unit or Vector3 .new(0,0,-1)
end
function bb.place(fic,gic)
local hic=V.isFarm(fic.id)
local iic,jic=bb.bestSpot(fic,hic or(bb.random and V.idol(fic.id)),(bb.trainee~=nil and fic.uuid==bb.trainee)or V.ENTRY[fic.id]==true or(bb.studyEntry==true and fic.id==bb.trialId))
if not iic then
bb.noSpot[fic.uuid]=(bb.noSpot[fic.uuid]or 0)+1
F.status(czd[3537],czd[3588]..V.name(fic.id))
return false
end
local kic=bb.money()
local lic,mic=F.request(czd[3589],czd[3590],fic.uuid,N.Util.CFramePLV(iic,bb.lookAt(iic)))
if lic and mic then
bb.spent=bb.spent+(fic.data.cost or 0)
table.insert(bb.actions,string.format(czd[3591],V.name(fic.id)))
F.log(1,czd[3543],string.format(czd[3592],V.name(fic.id),bb.spotKey(iic),jic,gic))
bb.placeLog=bb.placeLog or{}
table.insert(bb.placeLog,{t=math.floor(U.now()-(bb.startT or U.now())),w=bb.wave(),id=fic.id,x=math.floor(iic.X),z=math.floor(iic.Z),cover=math.floor((jic or 0)+0.5),why=tostring(gic):sub(1,90)})
F.status(czd[3537],string.format(czd[3593],V.name(fic.id),gic))
bb.placedAt=bb.placedAt or{}
bb.placedAt[fic.uuid]=(bb.placedAt[fic.uuid]or 0)+1
return true
end
if kic>=(fic.data.cost or 0)and bb.random then
bb.placeFail=bb.placeFail or{}
bb.placeFail[fic.uuid]=(bb.placeFail[fic.uuid]or 0)+1
if bb.placeFail[fic.uuid]>=2 then
bb.noSpot[fic.uuid]=3
F.log(1,czd[3543],string.format(czd[3594],V.name(fic.id),bb.fieldCount(),bb.FIELD_MAX))
end
end
if lic and kic>=(fic.data.cost or 0)and not bb.random then
local nic=bb.spotKey(iic)
bb.refused[nic]=true
local oic=bb.mapKey()
P.blocked[oic]=P.blocked[oic]or{}
if not bb.refusedRun[nic]then
P.blocked[oic][nic]=(tonumber(P.blocked[oic][nic])or 0)+1
bb.refusedRun[nic]=true
end
bb.refusals=(bb.refusals or 0)+1
bb.unitRefusals[fic.uuid]=(bb.unitRefusals[fic.uuid]or 0)+1
if bb.unitRefusals[fic.uuid]>=3 then
local pic=math.max(1,bb.count(fic.uuid))
if P.caps[fic.uuid]~=pic then
P.caps[fic.uuid]=pic
F.log(1,czd[3543],string.format(czd[3595],V.name(fic.id),pic))
end
end
F.log(2,czd[3543],czd[3596]..nic..czd[2325]..V.name(fic.id))
F.saveSoon()
end
return false
end
function bb.count(qic)
local ric=0
for sic,tic in ipairs({workspace._UNITS,workspace:FindFirstChild(czd[3597])})do
if tic then
for uic,vic in ipairs(tic:GetChildren())do
local wic=vic:FindFirstChild(czd[1746])
if wic and wic:FindFirstChild(czd[3586])and wic.player.Value==M and wic.uuid.Value==qic then
ric=ric+1
end
end
end
end
return ric
end
function bb.measure()
local xic,yic=bb.calRun,bb.info
if not(xic and yic)then
return
end
pcall(bb.sampleHelpers)
local zic=U.now()
local Aic=bb.wave()
local Bic=bb.money()
if not xic.start and Bic>0 and#bb.mine==0 then
xic.start=Bic
end
if Aic~=xic.lastW then
if bb.trialId and Aic>0 then
bb.trialTrace=bb.trialTrace or{}
local Cic,Dic,Eic,Fic=0,{},0,0
for Gic,Hic in ipairs(bb.mine)do
local Iic=Hic._stats
if Iic.id.Value==bb.trialId then
Cic=Cic+1
table.insert(Dic,tostring(Iic.upgrade.Value))
elseif not V.isFarm(Iic.id.Value)then
Fic=Fic+1
end
end
pcall(bb.sampleHelpers,true)
for Jic,Kic in pairs(bb.ownDealt)do
if Kic.id==bb.trialId then
Eic=Eic+Kic.v
end
end
local Lic=0
for Mic,Nic in pairs(bb.helperDealt)do
if Nic.owner==bb.trialId then
Lic=Lic+Nic.v
end
end
table.insert(bb.trialTrace,string.format(czd[3598],Aic,zic-(bb.startT or zic),Bic,table.concat(Dic,czd[2394]),Fic,Eic+Lic,#(bb.enemies or{}),bb.hpAliveRaw or 0,bb.waveMax[Aic-1]or 0,bb.teamDps or 0))
end
if xic.lastW and xic.lastW>0 and xic.lastWT then
table.insert(xic.waveSec,zic-xic.lastWT)
end
if xic.paidT and Aic>0 and zic-xic.paidT<15 then
table.insert(xic.skip,zic-xic.paidT)
end
xic.paidT=nil
if Aic>0 then
xic.alive[tostring(Aic)]=bb.hpAliveRaw or 0
end
xic.lastW,xic.lastWT=Aic,zic
end
local Oic=workspace:FindFirstChild(czd[3599])
if Oic and Aic>0 then
xic.timer[tostring(Aic)]=math.max(xic.timer[tostring(Aic)]or 0,tonumber(Oic.Value)or 0)
end
local Pic=Bic-(bb.lastMoneyR or Bic)
bb.lastMoneyR=Bic
bb.incomeLog=bb.incomeLog or{}
if Pic>0 then
table.insert(bb.incomeLog,{t=zic,y=Pic})
end
while bb.incomeLog[1]and zic-bb.incomeLog[1].t>30 do
table.remove(bb.incomeLog,1)
end
local Qic=0
for Ric,Sic in ipairs(bb.incomeLog)do
Qic=Qic+Sic.y
end
local Tic=math.min(30,zic-(bb.startT or zic))
bb.incomeRate=Tic>=8 and Qic/Tic or nil
for Uic,Vic in ipairs(bb.enemies)do
local Wic=Vic.m
local Xic=bb.track[Wic]
if not Xic then
local Yic=Wic._stats
local Zic=Wic:FindFirstChildOfClass(czd[3465])
local _ic=yic.cfgById[Yic.id.Value]
local ajc=_ic and fb.baseStats(yic,_ic)
if Zic and ajc and Aic>0 then
local bjc=ajc*yic.hpRaw*fb.waveScale(yic,Aic,yic.list[Aic])
if bjc>0 and Zic.MaxHealth>0 then
table.insert(xic.hp,Zic.MaxHealth/bjc)
end
end
bb.track[Wic]={t=zic,p=Vic.prog,sp=(Yic:FindFirstChild(czd[3600])and tonumber(Yic.speed.Value))or 1}
if Zic and Zic.MaxHealth>0 then
bb.enemyHpSum=(bb.enemyHpSum or 0)+Zic.MaxHealth
end
if Aic>0 then
xic.spawn[tostring(Aic)]=(xic.spawn[tostring(Aic)]or 0)+1
xic.spawnLast[tostring(Aic)]=zic-(xic.lastWT or zic)
end
elseif not Xic.done and zic-Xic.t>=15 then
Xic.done=true
local cjc=(Vic.prog-Xic.p)/(zic-Xic.t)/math.max(0.1,Xic.sp)
if cjc>0.001 and Vic.prog<0.95 then
table.insert(xic.walk,cjc)
end
end
end
local djc=0
for ejc,fjc in ipairs(bb.mine)do
local gjc=fjc._stats:FindFirstChild(czd[3601])
if gjc then
djc=djc+gjc.Value
end
end
xic.potSum=xic.potSum or 0
if xic.lastDealtT then
local hjc=zic-xic.lastDealtT
local ijc=0
xic.potBy=xic.potBy or{}
for jjc,kjc in ipairs(bb.mine)do
local ljc=kjc._stats
local mjc=ljc.id.Value
if not V.isFarm(mjc)and ljc:FindFirstChild(czd[3602])and ljc.target.Value~=nil then
local njc,ojc=pcall(bb.liveDps,kjc,mjc)
if njc and ojc then
ijc=ijc+ojc*hjc
local pjc=ojc/math.max(0.5,V.nudge(mjc))
local qjc,rjc=pcall(function()
return V.passive(mjc).mark
end)
if qjc and rjc and ljc:FindFirstChild(czd[1847])then
pjc=pjc+(tonumber(rjc.dot)or 0)*ljc.damage.Value
end
xic.potBy[mjc]=(xic.potBy[mjc]or 0)+pjc*hjc
end
end
end
xic.potWin=(xic.potWin or 0)+ijc
if zic-(xic.winT or zic)>=5 then
local sjc=djc-(xic.winDealt or djc)
if xic.potWin>0 and sjc>=0 then
xic.dealtSum=(xic.dealtSum or 0)+sjc
xic.potSum=xic.potSum+xic.potWin
end
xic.winT,xic.winDealt,xic.potWin=zic,djc,0
end
end
if not xic.winT then
xic.winT,xic.winDealt=zic,djc
end
xic.lastDealtT=zic
if Aic~=xic.dpsW and Aic>0 then
xic.dpsAt[tostring(Aic)]=bb.teamDps or 0
xic.dpsW=Aic
end
local tjc=math.min(1,zic-(xic.densT or zic))
xic.densT=zic
for ujc,vjc in ipairs(bb.enemies)do
local wjc=math.min(fb.BINS,math.floor(vjc.prog*fb.BINS)+1)
xic.dens[wjc]=(xic.dens[wjc]or 0)+tjc
end
local xjc=workspace._BASES.player:FindFirstChild(czd[3603])
local yjc=xjc and xjc:FindFirstChild(czd[3604])
local zjc=yjc and yjc:FindFirstChildOfClass(czd[3465])
if zjc then
xic.baseHp=math.max(xic.baseHp or 0,zjc.MaxHealth)
local Ajc=0
for Bjc,Cjc in ipairs(bb.enemies)do
if Cjc.prog>=0.97 then
local Djc=Cjc.m:FindFirstChildOfClass(czd[3465])
Ajc=Ajc+(Djc and Djc.MaxHealth or Cjc.hp)
end
end
if xic.lastBase and zjc.Health<xic.lastBase and Ajc>0 and xic.lastBaseT then
table.insert(xic.baseRel,(xic.lastBase-zjc.Health)/math.max(0.1,zic-xic.lastBaseT)/Ajc)
end
xic.lastBase,xic.lastBaseT=zjc.Health,zic
