function bb.holdGain(Amc,Bmc)
if bb.random or not Bmc or not bb.info then
return 0
end
local Cmc=V.attackInfo(Bmc.atk,Bmc.range)
if(Cmc.stun or 0)<=0 and(Cmc.slowTime or 0)<=0 then
return 0
end
local Dmc=0
for Emc,Fmc in ipairs(bb.mine or{})do
local Gmc=Fmc._stats
local Hmc=V.rows(Gmc.id.Value)
local Imc=Hmc and Hmc[math.min(Gmc.upgrade.Value,Hmc.max)]
local Jmc=Imc and Imc.atk and V.attackInfo(Imc.atk,Imc.range)
if Jmc and((Jmc.stun or 0)>0 or(Jmc.slowTime or 0)>0)then
Dmc=Dmc+1
end
end
local Kmc,Lmc=fb.mask(bb.info.map,V.range(Amc.u,0)*(bb.info.rangeScale or 1)),0
for Mmc=1,fb.BINS do
if Kmc[Mmc]then
Lmc=Lmc+1
end
end
local Nmc=bb.depth and bb.depth.units>0 and bb.depth.covEnd or 1
local Omc=(V.airFrom(Amc.id)==0)and 1 or(1-(1-N.FLY_GROUND)*math.min(1,bb.info.flyChance or 0))
return eb.holdGain(Cmc,bb.teamDps or 0,Lmc/(math.max(0.1,Nmc)*fb.BINS)*Omc,Dmc)
end
function bb.buffGain(Pmc)
local Qmc=V.allyBuff(Pmc.id)
if not Qmc then
return 0
end
local Rmc=bb.buffShort(Qmc)
local Smc=P.stack[Qmc.attack]
local Tmc=Smc and Smc.stacks and(Smc.cap or 1)or nil
local Umc,Vmc=pcall(V.range,Pmc.u,0)
Vmc=(Umc and tonumber(Vmc)or 15)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local Wmc=Tmc and O.community and tonumber(Qmc.time)and tonumber(Qmc.cd)
local function Xmc(Ymc,Zmc)
local _mc=math.floor(Ymc*Qmc.time/math.max(1,Qmc.cd)+0.001)
return math.min(Tmc,(1+Zmc)^_mc-1)
end
local anc=0
for bnc,cnc in ipairs(Rmc)do
local dnc=0
for enc,fnc in ipairs(Rmc)do
if(fnc.pos-cnc.pos).Magnitude<=Vmc then
local gnc=Qmc.types[fnc.base]
local hnc=gnc*Qmc.uptime
if Wmc then
local jnc,knc=Xmc(fnc.n,gnc),fnc.n+1
while knc<fnc.n+6 and Xmc(knc,gnc)<=jnc+0.001 do
knc=knc+1
end
hnc=math.max(0,(Xmc(knc,gnc)-jnc)/(knc-fnc.n))
elseif Tmc then
hnc=math.max(0,math.min(Tmc,(fnc.n+1)*gnc*Qmc.uptime)-math.min(Tmc,fnc.n*gnc*Qmc.uptime))
end
dnc=dnc+fnc.dps*hnc
end
end
anc=math.max(anc,dnc)
end
return anc*(Wmc and 1 or 0.7)
end
