bb.BASE_WIN,bb.BASE_MARGIN,bb.BASE_SOON,bb.BASE_END=10,1.3,45,0.97
function bb.baseVerdict(PAc,QAc)
local RAc=(QAc.t or 0)-(PAc.t or 0)
if RAc<bb.BASE_WIN-1 then
return false
end
local SAc=((tonumber(PAc.base)or 0)-(tonumber(QAc.base)or 0))/RAc
if SAc<=0 or(tonumber(QAc.base)or 0)<=0 then
return false
end
local TAc=QAc.base/SAc
local UAc,VAc=0,0
local WAc,XAc=PAc.foes or{},QAc.foes or{}
for YAc,ZAc in pairs(XAc)do
if ZAc.prog>=bb.BASE_END then
UAc=UAc+ZAc.hp
local _Ac=WAc[YAc]
if _Ac then
VAc=VAc+math.max(0,_Ac.hp-ZAc.hp)
end
end
end
for aBc,bBc in pairs(WAc)do
if bBc.prog>=bb.BASE_END and not XAc[aBc]then
VAc=VAc+bBc.hp
end
end
if UAc<=0 then
return false
end
local cBc=VAc/RAc
local dBc=cBc>0 and UAc/cBc or math.huge
local eBc={baseTime=TAc,loss=SAc,atEnd=UAc,rate=cBc,killTime=dBc}
return TAc<bb.BASE_SOON and dBc>TAc*bb.BASE_MARGIN,eBc
end
