if(bb.mergeIds[fEc]or fEc==bb.planId)and(mEc or UDc[fEc])and(not eEc or zEc>eEc.score)then
eEc={id=fEc,top=pEc,fresh=mEc,near=nEc or 0,n=oEc or 0,coming=UDc[fEc],score=zEc}
