local AEc,BEc=bb.wave(),(bb.total or 30)-bb.wave()
local CEc=(bb.pressure or 0)>=math.min(O.dangerReach,((bb.depth and bb.depth.units>0 and bb.depth.covEnd)or 1)*0.9)
local DEc=eEc.fresh
local EEc=not CEc and BEc>3
eEc.waits=DEc and DEc.lvl<=eEc.top.lvl and eEc.top.lvl<eEc.top.max and EEc or false
local FEc=(not DEc or DEc.lvl>=eEc.top.lvl)and eEc.coming and EEc
local GEc=bb.cloneCard and eEc.top.lvl>=eEc.top.max and EEc
