function db.fit(PPc)
local QPc=U.json(PPc)
if#QPc<=3900 then
return QPc
end
for RPc,SPc in ipairs({2,5,10})do
local TPc={}
for UPc,VPc in ipairs(PPc.waves or{})do
if UPc%SPc==0 or UPc== #PPc.waves then
table.insert(TPc,VPc)
end
end
PPc.waves=TPc
QPc=U.json(PPc)
if#QPc<=3900 then
return QPc
end
end
for WPc,XPc in ipairs(PPc.placed or{})do
XPc.why=nil
end
QPc=U.json(PPc)
if#QPc<=3900 then
return QPc
end
if PPc.mapData then
PPc.mapData.dens=nil
end
QPc=U.json(PPc)
if#QPc<=3900 then
return QPc
end
PPc.placed,PPc.plan=nil,nil
return U.json(PPc):sub(1,3900)
end
